(36505, 'Joshua 11:8', 'Joshua', 11, 8, 'څښتن اسراییلیان په هغوی باندې بریالي کړل. اسراییلیانو په هغوی باندې حمله وکړه او په شمال کې یې تر مسرفوت مایم او لوی صیدون او په ختیځ کې د مصفه تر درې پورې تعقیب کړل. جګړه تر هغه وخته پورې روانه وه، ترڅو چې د دښمن له خوا هېڅوک ژوندی پاتې نه شو.', 'چشتن اسراییلیان په هغوی باندې بریالی کرل. اسراییلیانو په هغوی باندې حمله وکره او په شمال کې یې تر مسرفوت مایم او لوی صیدون او په ختیج کې د مصفه تر درې پورې تعقیب کرل. جګره تر هغه وخته پورې روانه وه، ترچو چې د دشمن له خوا هېچوک ژوندی پاتې نه شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36506, 'Joshua 11:9', 'Joshua', 11, 9, 'یوشع د هغوی سره هماغه شان کار وکړ څنګه چې څښتن هغه ته حکم کړی ؤ. هغه د هغوی اسونه ګوډ کړل او د هغوی جنګي ګاډۍ یې وسوځولې.', 'یوشع د هغوی سره هماغه شان کار وکر چنګه چې چشتن هغه ته حکم کری و. هغه د هغوی اسونه ګود کرل او د هغوی جنګی ګادی یې وسوجولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36507, 'Joshua 11:10', 'Joshua', 11, 10, 'یوشع بېرته راوګرځېد، هغه د حاصور ښار ونیوه او د هغه ځای پاچا یې وواژه. (په هغه وخت کې نورې پاچاهۍ چې پورته ورڅخه یادونه وشوه، د حاصور د پاچا تر واکمنۍ لاندې وې.)', 'یوشع بېرته راوګرجېد، هغه د حاصور شار ونیوه او د هغه جای پاچا یې وواژه. (په هغه وخت کې نورې پاچاهی چې پورته ورچخه یادونه وشوه، د حاصور د پاچا تر واکمنی لاندې وې.)', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36508, 'Joshua 11:11', 'Joshua', 11, 11, 'هغوی هلته ټول خلک ووژل. هېڅوک ژوندی پاتې نه شو او ښار یې وسوځاوه.', 'هغوی هلته تول خلک ووژل. هېچوک ژوندی پاتې نه شو او شار یې وسوجاوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36509, 'Joshua 11:12', 'Joshua', 11, 12, 'یوشع هغه ټول ښارونه د هغو د پاچاهانو سره ونیول او ټول یې ووژل. لکه څنګه چې د څښتن خدمتګار موسی امر کړی ؤ، یوشع هغوی په پوره توګه له منځه یووړل.', 'یوشع هغه تول شارونه د هغو د پاچاهانو سره ونیول او تول یې ووژل. لکه چنګه چې د چشتن خدمتګار موسی امر کری و، یوشع هغوی په پوره توګه له منجه یوورل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36510, 'Joshua 11:13', 'Joshua', 11, 13, 'خو بیاهم، اسراییلیانو د هغو ښارونو څخه چې په غونډیو باندې ودان شوي وو هېڅ کوم ښار ونه سوځاوه، پرته له حاصور څخه چې یوشع هغه وسوځاوه.', 'خو بیاهم، اسراییلیانو د هغو شارونو چخه چې په غوندیو باندې ودان شوی وو هېچ کوم شار ونه سوجاوه، پرته له حاصور چخه چې یوشع هغه وسوجاوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36511, 'Joshua 11:14', 'Joshua', 11, 14, 'د اسراییلو خلکو د دې ښارونو څخه ټول قیمتي شیان او څاروي یووړل او د ځانونو دپاره یې وساتل. خو هغوی ټول خلک ووژل، هېڅوک هم ژوندی پاتې نه شو.', 'د اسراییلو خلکو د دې شارونو چخه تول قیمتی شیان او چاروی یوورل او د جانونو دپاره یې وساتل. خو هغوی تول خلک ووژل، هېچوک هم ژوندی پاتې نه شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36512, 'Joshua 11:15', 'Joshua', 11, 15, 'څښتن خپل خدمتګار موسی ته حکمونه ورکړي وو، موسی هغه یوشع ته ورکړل او یوشع هغه سرته ورسول. یوشع هغه ټول کارونه تر سره کړل چې څښتن په موسی باندې د هغو حکم کړی ؤ.', 'چشتن خپل خدمتګار موسی ته حکمونه ورکری وو، موسی هغه یوشع ته ورکرل او یوشع هغه سرته ورسول. یوشع هغه تول کارونه تر سره کرل چې چشتن په موسی باندې د هغو حکم کری و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36513, 'Joshua 11:16', 'Joshua', 11, 16, 'نو یوشع دغه ټوله خاوره ونیوله: غرنۍ سیمه، د غرونو لوېدیځې لمنې، شمال او جنوب دواړه، د جوشن ټوله سیمه، ټوله جنوبي دښته او د اردن دره.', 'نو یوشع دغه توله خاوره ونیوله: غرنی سیمه، د غرونو لوېدیجې لمنې، شمال او جنوب دواره، د جوشن توله سیمه، توله جنوبی دشته او د اردن دره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36514, 'Joshua 11:21', 'Joshua', 11, 21, 'په هغه وخت کې یوشع عناقیان چې لوړ قدونه یې درلودل او په حبرون، دبیر، عناب او د یهودا او اسراییلو په پاتې ټولو غرنیو سیمو کې اوسېدل هم له منځه یووړل. یوشع هغوی د خپلو ښارونو سره بیخي له منځه یووړل.', 'په هغه وخت کې یوشع عناقیان چې لور قدونه یې درلودل او په حبرون، دبیر، عناب او د یهودا او اسراییلو په پاتې تولو غرنیو سیمو کې اوسېدل هم له منجه یوورل. یوشع هغوی د خپلو شارونو سره بیخی له منجه یوورل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36515, 'Joshua 11:22', 'Joshua', 11, 22, 'د عناقیانو څخه هېڅوک د اسراییلیانو په خاوره کې پاتې نه شو، یوازې په غزه، جت او اشدود کې ځینې خلک ژوندي پاتې شول.', 'د عناقیانو چخه هېچوک د اسراییلیانو په خاوره کې پاتې نه شو، یوازې په غزه، جت او اشدود کې جینې خلک ژوندی پاتې شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_11_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36516, 'Joshua 11:23', 'Joshua', 11, 23, 'څنګه چې څښتن موسی ته لارښوونه کړې وه، یوشع ټوله خاوره ونیوله او هغه یې اسراییلیانو ته د هغوی د خپل ملکیت په توګه ورکړه. هغه یې په څو برخو ووېشله، هرې قبیلې ته یوه برخه ورسېدله. په پای کې په هغه هېواد کې ارامي شوه.', 'چنګه چې چشتن موسی ته لارشوونه کرې وه، یوشع توله خاوره ونیوله او هغه یې اسراییلیانو ته د هغوی د خپل ملکیت په توګه ورکره. هغه یې په چو برخو ووېشله، هرې قبیلې ته یوه برخه ورسېدله. په پای کې په هغه هېواد کې ارامی شوه.', 'OT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
